def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is not None and math.isfinite(v) and v > 0:
        return float(v)
    v = s.get('lattice', {}).get('volume_A3')
    w = sum(max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in s.get('sites', []))
    if v is not None and math.isfinite(v) and v > 0 and w > 0:
        return float(v / w)
    return 0.0

def feature(s):
    sites = s.get('sites', [])
    props = s.get('element_properties', {})
    v = s.get('lattice', {}).get('volume_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        a = s.get('volume_per_atom_A3')
        w = sum(max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites)
        v = a * w if a is not None and math.isfinite(a) else 0.0
    if v <= 0:
        return 0.0
    total = 0.0
    for t in sites:
        r = props.get(t.get('element'), {}).get('covalent_radius_A')
        if r is not None and math.isfinite(r) and r > 0:
            total += max(0.0, float(t.get('occupancy', 1.0) or 0.0)) * r * r * r
    return float(4.0 * math.pi * total / (3.0 * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    elements = [t.get('element') for t in sites]
    nearest = [math.inf for t in sites]
    neighbors = s.get('neighbors', [])
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and math.isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    weight = 0.0
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and math.isfinite(d) and 0 < d <= 1.3 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if elements[i] != elements[j]:
                unlike += w
    fractions = [float(x) for x in s.get('composition', {}).values() if x is not None and math.isfinite(x) and x > 0]
    total = sum(fractions)
    if weight <= 0 or total <= 0:
        return 0.0
    expected = 1.0 - sum((x / total) ** 2 for x in fractions)
    return float(unlike / weight - expected)

def feature(s):
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        value = props.get(e, {}).get('first_ionization_energy_eV')
        if x is not None and math.isfinite(x) and x > 0 and value is not None and math.isfinite(value):
            total += x * value
            weight += x
    return float(total / weight) if weight > 0 else 0.0

